import{c as a,Q as e,j as d,m as r}from"./chunks/framework.DOi4mjdC.js";const A=JSON.parse('{"title":"SetLoadDataRepeat","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetLoadDataRepeat","slug":"setloaddatarepeat"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetLoadDataRepeat.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetLoadDataRepeat.md"}'),l={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetLoadDataRepeat.md"};function o(i,t,s,p,h,n){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="setloaddatarepeat" tabindex="-1">SetLoadDataRepeat <a class="header-anchor" href="#setloaddatarepeat" aria-label="Permalink to &quot;SetLoadDataRepeat&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于设置<a href="./LoadData/Load3D.html#li83241850104315">Load3Dv2接口</a>的repeat参数。设置repeat参数后，可以通过调用一次Load3Dv2接口完成多个迭代的数据搬运。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetLoadDataRepeat(const LoadDataRepeatParam&amp; repeatParams)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>repeatParams</td><td>输入</td><td>设置Load3Dv2接口的repeat参数，类型为LoadDataRepeatParam。 具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。 参数说明请参考表2。</td></tr></tbody></table><p><strong>表 2</strong> LoadDataRepeatParam结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>repeatStride</td><td>height/width方向上的前一个迭代与后一个迭代起始地址的距离，取值范围：n∈[0, 65535]，默认值为0。 repeatMode为0，repeatStride的单位为16个元素。repeatMode为1，repeatStride的单位和具体型号有关。下文中的data_type指Load3Dv2中源操作数的数据类型。 Ascend 950PR/Ascend 950DT，repeatStride的单位为32/sizeof(data_type)个元素 。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，repeatStride的单位为32/sizeof(data_type)个元素 。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，repeatStride的单位为32/sizeof(data_type)个元素 。 Atlas 200I/500 A2 推理产品，repeatStride的单位为64/sizeof(data_type)个元素。</td></tr><tr><td>repeatTime</td><td>height/width方向上的迭代次数，取值范围：repeatTime ∈[0, 255] 。默认值为1。</td></tr><tr><td>repeatMode</td><td>控制repeat迭代的方向，取值范围：k∈[0, 1] 。默认值为0。 0：迭代沿height方向； 1：迭代沿width方向。</td></tr></tbody></table><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>参考<a href="./SetFmatrix.html#section642mcpsimp">调用示例</a></p>',14)])])}const _=a(l,[["render",o]]);export{A as __pageData,_ as default};
